from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


# ── TaskQuery validation ─────────────────────────────────────────────

class TestTaskQuery:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="nonexistent")

    @pytest.mark.parametrize("limit", [0, -1, 101, "five"])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=limit)

    @pytest.mark.parametrize("offset", [-1, "two"])
    def test_invalid_offset_raises(self, offset):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=offset)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  My-Tag  ")
        assert q.tag == "my-tag"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_blank_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_is_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


# ── TaskPage ─────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[Task(id=1, title="T")], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[Task(id=1, title="T")], total=1, limit=2, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact_boundary(self):
        items = [Task(id=1, title="A"), Task(id=2, title="B")]
        page = TaskPage(items=items, total=2, limit=2, offset=0)
        assert page.has_more is False


# ── apply_query — filtering ──────────────────────────────────────────

class TestApplyQueryFilter:
    @pytest.fixture
    def tasks(self, sample_tasks):
        return sample_tasks

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_by_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 3

    def test_filter_by_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].title == "Write report"

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="work"), NOW)
        assert page.total == 2
        titles = {t.title for t in page.items}
        assert titles == {"Write report", "Deploy v2"}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="report"), NOW)
        assert page.total == 1
        assert page.items[0].title == "Write report"

    def test_search_is_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BUY"), NOW)
        assert page.total == 1

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].title == "Call dentist"

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # Excludes the overdue task
        assert all(not t.is_overdue(NOW) for t in page.items)

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="personal"), NOW)
        titles = {t.title for t in page.items}
        assert titles == {"Buy groceries", "Call dentist"}


# ── apply_query — sorting ────────────────────────────────────────────

class TestApplyQuerySort:
    @pytest.fixture
    def tasks(self, sample_tasks):
        return sample_tasks

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        ids = [t.id for t in page.items]
        assert ids == [1, 2, 3, 4]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        ids = [t.id for t in page.items]
        assert ids == [4, 3, 2, 1]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        # HIGH first, then MEDIUM, then LOW
        assert priorities == [
            TaskPriority.HIGH, TaskPriority.HIGH,
            TaskPriority.MEDIUM, TaskPriority.LOW,
        ]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Tasks with due_at come first, None-due tasks come last
        due_values = [t.due_at for t in page.items]
        none_indices = [i for i, d in enumerate(due_values) if d is None]
        non_none_indices = [i for i, d in enumerate(due_values) if d is not None]
        if none_indices and non_none_indices:
            assert min(none_indices) > max(non_none_indices)


# ── apply_query — pagination ─────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self, sample_tasks):
        return sample_tasks

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 4
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=2), NOW)
        assert len(page.items) == 2
        assert page.offset == 2

    def test_offset_past_end(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert page.items == []
        assert page.total == 4
        assert page.has_more is False

    def test_exact_page_boundary(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=4), NOW)
        assert len(page.items) == 4
        assert page.has_more is False

